-- us_zctas and vehicle_location_observations.zcta: the ZIP level of the one map, keyed in the database, drawn from tiles.
--
-- WHY. The map's third level is the ZIP, and today only iOS has it, by fetching ZCTA polygons live from Census
-- TIGERweb per county. Measured first (scripts/map/build-zcta.mjs, 2026-10-20): the Census 2020 ZCTA cartographic file
-- (1:500,000) is 33,791 polygons, 5,954,485 vertices, 130 MB as GeoJSON (38.5 MB gzipped). Those polygons stay out of
-- the production database (204 GB on 2026-10-19) and are served as vector tiles from storage (build-tiles.mjs). The
-- database holds only membership: which five-digit codes are ZCTAs and which county holds most of each one's land, so
-- a location row can carry a zcta key and a fold can count by it. Of 12,005 distinct postal codes seen in the 30 days to
-- 2026-10-20, 11,324 are ZCTAs; the 681 that are not (post-office-box ZIPs) stay unkeyed at ZIP level and are reported
-- as "no ZIP". No point-in-ZCTA fallback: a city-grain point (Facebook) would key a whole city to one ZIP.
--
-- WHAT.
--   1. us_zctas: the place entity at ZIP grain, 33,791 rows (zcta, county_fips with the largest land-area share,
--      state_fips), from the Census 2020 ZCTA-to-county relationship file (tab20_zcta520_county20_natl.txt). Eight
--      Alaska ZCTAs name counties 02063 and 02066 (Chugach and Copper River, 2019) that us_county_boundaries, an older
--      release, lacks; county_fips is therefore not a foreign key. Reference data written only by migrations; every
--      role reads it.
--   2. vehicle_location_observations.zcta: set BEFORE INSERT, or UPDATE OF postal_code, by trg_key_vehicle_location_zcta
--      when left(postal_code, 5) is a ZCTA; otherwise left NULL. Fires only when zcta is NULL.
--   3. key_vehicle_location_zcta(p_batch): the back-fill writer for existing rows (service_role, receipted in
--      write_receipts, SKIP LOCKED, idempotent), run once after the deploy with before/after counts in the PR.
--   4. A partial index on zcta, built concurrently after the transaction, for the ZIP-level fold.
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

CREATE TABLE IF NOT EXISTS public.us_zctas (
  zcta        text PRIMARY KEY CHECK (zcta ~ '^[0-9]{5}$'),
  county_fips text NOT NULL CHECK (county_fips ~ '^[0-9]{5}$'),
  state_fips  text GENERATED ALWAYS AS (left(county_fips, 2)) STORED,
  source      text NOT NULL DEFAULT 'census_2020_zcta_county_rel'
);
COMMENT ON TABLE public.us_zctas IS
'The place entity at ZIP grain: one row per Census 2020 ZIP Code Tabulation Area (grain: one ZCTA; PRIMARY KEY zcta). 33,791 rows from the Census 2020 ZCTA-to-county relationship file. Membership only: the polygons are vector tiles in storage (scripts/map/build-zcta.mjs, build-tiles.mjs), never rows here. A postal code that is not a ZCTA (post-office boxes, unique ZIPs) has no row and no ZIP-level place. Reference data written only by migrations (20261020210000); readable by every role.';
COMMENT ON COLUMN public.us_zctas.zcta IS 'The five-digit ZCTA code, the key; equals the ZIP code for every ZIP that is a ZCTA.';
COMMENT ON COLUMN public.us_zctas.county_fips IS 'The county holding the largest share of the ZCTA''s land area (AREALAND_PART). A ZCTA can straddle counties; this is the one it rolls up to. Not a foreign key: eight Alaska ZCTAs name 2019 counties us_county_boundaries lacks.';
COMMENT ON COLUMN public.us_zctas.state_fips IS 'left(county_fips, 2): the state the ZCTA rolls up to (us_states.fips).';
COMMENT ON COLUMN public.us_zctas.source IS 'The release the row comes from.';

-- 33,791 (zcta, county) pairs, ten characters each, in one literal, unpacked in one pass (substr per pair detoasts the
-- literal each call: 80 s on the contract's PG17).
INSERT INTO public.us_zctas (zcta, county_fips)
SELECT m[1], m[2]
FROM (SELECT ''
