ALTER TABLE public.us_zctas ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS us_zctas_read ON public.us_zctas;
CREATE POLICY us_zctas_read ON public.us_zctas FOR SELECT USING (true);
REVOKE ALL ON public.us_zctas FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.us_zctas TO anon, authenticated, service_role;

ALTER TABLE public.vehicle_location_observations ADD COLUMN IF NOT EXISTS zcta text;
COMMENT ON COLUMN public.vehicle_location_observations.zcta IS
'The ZIP-level place key: left(postal_code, 5) when that code is a 2020 ZCTA (us_zctas), else NULL. Set at insert and when postal_code changes by trg_key_vehicle_location_zcta; existing rows by key_vehicle_location_zcta(). NULL means no ZIP-level place (no postal code, or a code that is not a ZCTA); the map reports those as "no ZIP". Migration 20261020210000.';

CREATE OR REPLACE FUNCTION public.key_vehicle_location_zcta()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  SELECT z.zcta INTO NEW.zcta FROM public.us_zctas z WHERE z.zcta = left(NEW.postal_code, 5);
  RETURN NEW;
END
$$;
COMMENT ON FUNCTION public.key_vehicle_location_zcta() IS
'BEFORE INSERT OR UPDATE OF postal_code trigger function on vehicle_location_observations (trg_key_vehicle_location_zcta, migration 20261020210000): sets zcta to left(postal_code, 5) when us_zctas has it, else leaves it NULL. Never raises.';

DROP TRIGGER IF EXISTS trg_key_vehicle_location_zcta ON public.vehicle_location_observations;
CREATE TRIGGER trg_key_vehicle_location_zcta
BEFORE INSERT OR UPDATE OF postal_code ON public.vehicle_location_observations
FOR EACH ROW
WHEN (NEW.zcta IS NULL AND NEW.postal_code ~ '^[0-9]{5}')
EXECUTE FUNCTION public.key_vehicle_location_zcta();
COMMENT ON TRIGGER trg_key_vehicle_location_zcta ON public.vehicle_location_observations IS
'Keys zcta from postal_code at insert and when the postal code of an unkeyed row changes; see key_vehicle_location_zcta(). Fires only when zcta is NULL and postal_code starts with five digits.';

CREATE OR REPLACE FUNCTION public.key_vehicle_location_zcta(p_batch integer DEFAULT 10000)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  c_writer      constant text := 'key_vehicle_location_zcta';
  v_prev_writer text := current_setting('app.writer', true);
  v_started     timestamptz := clock_timestamp();
  v_keyed       integer := 0;
BEGIN
  IF p_batch IS NULL OR p_batch < 1 OR p_batch > 20000 THEN
    RAISE EXCEPTION 'key_vehicle_location_zcta: p_batch must be between 1 and 20000, got %', p_batch
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  PERFORM set_config('app.writer', c_writer, true);

  -- Only rows whose code is a ZCTA enter the batch, so a non-ZCTA code never blocks the walk.
  WITH pick AS (
    SELECT o.id, z.zcta
    FROM public.vehicle_location_observations o
    JOIN public.us_zctas z ON z.zcta = left(o.postal_code, 5)
    WHERE o.zcta IS NULL AND o.postal_code ~ '^[0-9]{5}'
    LIMIT p_batch
    FOR UPDATE OF o SKIP LOCKED
  ), upd AS (
    UPDATE public.vehicle_location_observations o SET zcta = p.zcta FROM pick p WHERE p.id = o.id RETURNING 1
  )
  SELECT count(*) INTO v_keyed FROM upd;

  IF v_keyed > 0 THEN
    INSERT INTO public.write_receipts (tbl, op, rows, writer, db_role, app_name, txid)
    VALUES ('vehicle_location_observations', 'UPDATE', v_keyed, c_writer, current_user,
            current_setting('application_name', true), txid_current());
  END IF;
  PERFORM set_config('app.writer', coalesce(v_prev_writer, ''), true);
  RETURN jsonb_build_object('keyed', v_keyed, 'batch', p_batch,
                            'ms', round(extract(epoch FROM clock_timestamp() - v_started) * 1000));
END
$$;
REVOKE ALL ON FUNCTION public.key_vehicle_location_zcta(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.key_vehicle_location_zcta(integer) TO service_role;
COMMENT ON FUNCTION public.key_vehicle_location_zcta(integer) IS
'Back-fill writer: keys zcta on up to p_batch (1..20000, default 10000) vehicle_location_observations rows that have none and whose postal code is a ZCTA, oldest-locked-first with SKIP LOCKED; records a write_receipts row; returns {keyed, batch, ms}. SECURITY DEFINER, service_role only. Idempotent: run until keyed = 0. Migration 20261020210000.';

COMMIT;

-- Outside the transaction: the ZIP-level fold reads by zcta.
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_vehicle_location_observations_zcta
  ON public.vehicle_location_observations (zcta) WHERE zcta IS NOT NULL;
